import{_ as r,h as i,i as t,c as n,v as e,p as d,x as o,m as l,e as m,S as p}from"./chunks/framework.Dvtg8yj2.js";const x=JSON.parse('{"title":"Scaled Dot-Product Attention","description":"","frontmatter":{"title":"Scaled Dot-Product Attention","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sdpa.md","filePath":"llm/sdpa.md","lastUpdated":1788454257000}'),_={name:"llm/sdpa.md"};function h(c,a,f,u,A,k){const s=i("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="scaled-dot-product-attention" tabindex="-1">Scaled Dot-Product Attention <a class="header-anchor" href="#scaled-dot-product-attention" aria-label="Permalink to &quot;Scaled Dot-Product Attention&quot;">​</a></h1><div class="epigraph"><p>我们将点积除以键向量维度的平方根，以免点积量级随维度膨胀、把 softmax 推入梯度几乎为零的饱和区。</p><footer>—— Vaswani et al., Attention Is All You Need, NeurIPS 2017</footer></div><p>注意力要回答的问题很朴素：给定一条查询，当前上下文里哪些位置值得读、该以多大权重去读。2017 年 Transformer 把这个问题收成一个可并行的矩阵运算——缩放点积注意力（Scaled Dot-Product Attention, SDPA）。它是后续多头、因果掩码、交叉注意力共用的计算内核：先打分，再归一化，最后对值加权。Bahdanau 等人更早的加性注意力在效果上并非不能用，但点积能直接走密集矩阵乘，更适合当时已经成熟的 GPU 原语；Vaswani 等人要补的，只是点积随维度放大这一条数值缺陷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>序列模型需要一种内容寻址：不是按固定偏移去取邻居，而是按查询与键的相容性去取。循环网络靠隐状态逐步传递，远距离依赖要穿过许多时间步；卷积的感受野随层数线性或指数扩张，但仍是局部的。注意力把任意两个位置的交互变成一次打分，理论上是全连接的。</p><p>相容性函数有两条主流路。加性注意力把查询与键拼起来，过一层非线性再投影成标量，表达力强，却多一次仿射与激活，难以与大矩阵乘融合。点积注意力直接算 \\(q^\\top k\\)，硬件友好，但当键的维度 \\(d_k\\) 增大时，若各分量近似独立，点积的方差大约按 \\(d_k\\) 增长。方差一大，softmax 的输入就极易两极分化：最大值对应的权重接近 1，其余接近 0，梯度几乎为零。训练初期若再叠加深层，优化会变得很脆。</p><h3 id="点积方差随维度膨胀" tabindex="-1">点积方差随维度膨胀 <a class="header-anchor" href="#点积方差随维度膨胀" aria-label="Permalink to &quot;点积方差随维度膨胀&quot;">​</a></h3><p>设 \\(q, k \\in \\mathbb{R}^{d_k}\\) 的分量独立、均值为 0、方差为 1，则</p> \\[\\mathbb{E}[q^\\top k] = 0, \\qquad \\mathrm{Var}(q^\\top k) = d_k. \\]<p>标准差是 \\(\\sqrt{d_k}\\)。\\(d_k=64\\) 时已经把 logits 拉到大约 8 的量级；\\(d_k=128\\) 更夸张。softmax 对这种尺度极为敏感。SDPA 要解决的，不是「要不要注意力」，而是「点积作为打分函数时，如何让尺度与 \\(d_k\\) 解耦」。</p><p><span class="marginnote">很多人把 \\(1/\\sqrt{d_k}\\) 理解成「除一个常数让数变小」。更准确的说法是：它把点积的标准差从 \\(\\sqrt{d_k}\\) 拉回到大约 1，使 softmax 工作在梯度尚存的区间。温度、学习率、初始化方差都会改变同一件事的数值表现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SDPA 的输入是三个矩阵：查询 \\(Q \\in \\mathbb{R}^{n \\times d_k}\\)、键 \\(K \\in \\mathbb{R}^{m \\times d_k}\\)、值 \\(V \\in \\mathbb{R}^{m \\times d_v}\\)。自注意力里通常 \\(n=m\\) 且三者来自同一组表示；交叉注意力里 \\(n\\) 与 \\(m\\) 可以不同。公式是</p> \\[\\mathrm{Attention}(Q, K, V) = \\mathrm{softmax}\\left(\\frac{QK^\\top}{\\sqrt{d_k}}\\right) V. \\]<p>先算分数矩阵 \\(S = QK^\\top / \\sqrt{d_k} \\in \\mathbb{R}^{n \\times m}\\)，再沿键的那一维做 softmax，得到权重 \\(A\\)，最后 \\(AV\\) 把值混成每条查询的输出。缩放只作用于分数，不改变值向量本身。</p><h3 id="一次前向里的三个线性代数步骤" tabindex="-1">一次前向里的三个线性代数步骤 <a class="header-anchor" href="#一次前向里的三个线性代数步骤" aria-label="Permalink to &quot;一次前向里的三个线性代数步骤&quot;">​</a></h3><p>实现上几乎总是先做查询与键转置的乘，再除 \\(\\sqrt{d_k}\\) 或乘预先算好的倒数，然后 softmax，再拿权重乘值。掩码——因果或 padding——加在 softmax 之前，通常是把无效位置写成一个很大的负数，以免归一化时分到质量。这一内核后来被 FlashAttention 在片上存储里分块重算，但数学对象没有变：仍然是缩放点积加 softmax 加权。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缩放的作用可以从 softmax 的 Jacobian 看。对向量 \\(z\\)，softmax 输出 \\(p_i = e^{z_i} / \\sum_j e^{z_j}\\)，对角元约为 \\(p_i(1-p_i)\\)。当某个 \\(z_i\\) 远大于其余，\\(p\\) 接近 one-hot，Jacobian 接近零。除以 \\(\\sqrt{d_k}\\) 等价于把 logits 的典型幅度固定下来，避免「维度越大越接近硬选择」。</p><p>与温度的关系是直接的。若定义</p> \\[p = \\mathrm{softmax}(s / \\tau), \\]<p>SDPA 相当于取 \\(\\tau = \\sqrt{d_k}\\)。训练时这个温度通常不作为可学习参数，而是由宽度决定的常数；推理时有人会另设温度，那是在已经训练好的分数上再调锋利程度，和训练稳定性不是同一件事。</p><p><span class="marginnote">缩放不能替代正确的初始化。若查询、键的投影把表示放到过大的尺度，除 \\(\\sqrt{d_k}\\) 之后 logits 仍然可能饱和。反过来，过小的初始化会让注意力接近均匀，模型短期看起来什么都在看，有效上下文被稀释。</span></p><h3 id="与加性注意力的计算差异" tabindex="-1">与加性注意力的计算差异 <a class="header-anchor" href="#与加性注意力的计算差异" aria-label="Permalink to &quot;与加性注意力的计算差异&quot;">​</a></h3><p>加性注意力的分数是 \\(v^\\top \\tanh(W_q q + W_k k)\\)，每个查询-键对都要走一遍非线性；点积是一次 \\(n \\times d\\) 与 \\(d \\times m\\) 的乘。序列一长，前者的元素级开销会压过矩阵乘的吞吐优势。Transformer 选点积，是把能走通用矩阵乘当成一等约束，再用缩放把数值补回来。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>SDPA 假定键、查询处在同一点积空间，维度必须一致；值的维度可以不同，但现代实现几乎总取 \\(d_v=d_k\\) 以便拼头。它对长度没有结构先验：两个位置只要分数高就可以强耦合，这也是二次复杂度的根源——分数矩阵是 \\(n \\times m\\) 的稠密表。</p><p>数值上，softmax 应在较高精度里做，或先减行最大值再指数。半精度训练时 \\(QK^\\top\\) 的中间结果容易溢出，这不是缩放公式的问题，而是浮点动态范围的问题。长度外推、稀疏模式、线性注意力，都是在 SDPA 之外改连通性或核函数，并不替换「缩放点积加 softmax」这一默认内核。</p><p><span class="marginnote">不要把 SDPA 和已经算完的注意力权重可视化混为一谈。权重是 softmax 之后的行随机矩阵；真正参与残差流的是加权后的值。只看权重会高估某些高分但值向量近零的位置，也会低估分数平庸但值很大的位置。</span></p>',29)),(t(),d(p,null,{default:o(()=>[m(s,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Query%20Q%22%5D%20--%3E%20S%5B%22%E7%BC%A9%E6%94%BE%E7%82%B9%E7%A7%AF%E5%88%86%E6%95%B0%22%5D%0A%20%20K%5B%22Key%20K%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20M%5B%22%E5%8F%AF%E9%80%89%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20P%5B%22Softmax%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20P%20--%3E%20O%5B%22%E5%8A%A0%E6%9D%83%E6%B1%82%E5%92%8C%22%5D%0A%20%20V%5B%22Value%20V%22%5D%20--%3E%20O%0A%20%20O%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缩放点积注意力用 \\(QK^\\top/\\sqrt{d_k}\\) 作为相容性，再用 softmax 对值加权，是 Transformer 注意力的计算内核。</li><li>除 \\(\\sqrt{d_k}\\) 是为了对消点积方差随维度线性增长，避免 softmax 饱和。</li><li>相对加性注意力，点积能整段落成矩阵乘，更适合 GPU；缩放是为此付出的数值代价的补偿。</li><li>掩码加在 softmax 之前；值的混合发生在权重之后，可视化权重不等于可视化贡献。</li><li>公式不包含长度先验，故分数矩阵随序列长度二次增长。</li><li>半精度下的溢出、温度调节、后续的多头与因果约束，都建立在这一内核之上，而不是改写它。</li><li>出处：Vaswani et al., <em>Attention Is All You Need</em>, NeurIPS 2017。</li></ul>',2))])}const b=r(_,[["render",h]]);export{x as __pageData,b as default};
